#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>
using namespace std;

int main() {
    int N, M, K;
    cin >> N >> M >> K;
    vector<int> H(N), B(M);
    for (auto&& h : H)
        cin >> h;
    for (auto&& b : B)
        cin >> b;

    // 軽いほうから並べて
    ranges::sort(H);
    ranges::sort(B);

    // 頭の先頭 K 個と体の末尾 K 個のうち、軽いほうから見て頭のほうが重いペアがあれば No 、なければ Yes
    cout << (transform_reduce(begin(H), begin(H) + K, end(B) - K, false, logical_or{}, greater{}) ? "No" : "Yes") << endl;
    return 0;
}
